"use client";

import React, { useState, useRef, useEffect } from "react";
import styles from "../page.module.css";

type Message = { from: "ai" | "user"; text: string };

// IA via OpenAI API (GPT-4o) via API interne sécurisée
async function callGrokAPI(messages: Message[]): Promise<string> {
  const res = await fetch("/api/ask-ai", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ messages }),
  });
  const data = await res.json();
  return data.reply || "";
}

export default function SquareAIFloat() {
  const [open, setOpen] = useState(false);
  type Message = { from: "ai" | "user"; text: string };
  const [messages, setMessages] = useState<Message[]>([
    { from: "ai", text: "Bonjour, je suis Nérethense, prêt à aider avec vos rapports. Posez-moi une question !" },
  ]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (messagesEndRef.current) {
      messagesEndRef.current.scrollIntoView({ behavior: "smooth" });
    }
  }, [messages, loading]);

  async function sendMessage() {
    if (!input.trim()) return;
    const userMessage: Message = { from: "user", text: input };
    setMessages((msgs) => [...msgs, userMessage]);
    setLoading(true);
    setInput("");

    // Envoie l'historique complet pour le contexte
    const reply = await callGrokAPI([...messages, userMessage]);
    setMessages((msgs) => [...msgs, { from: "ai", text: reply }]);
    setLoading(false);
  }

  return (
    <div
      style={{
        position: "fixed",
        bottom: 32,
        right: 32,
        zIndex: 9999,
        background: "#23272e", // Fond plus clair mais sombre, adapté au thème report
        borderRadius: 18,
        boxShadow: "0 2px 16px rgba(0,0,0,0.12)",
        padding: 28,
        minWidth: 320,
        maxWidth: 400,
        border: "1px solid #353a40",
        display: "flex",
        flexDirection: "column",
        transition: "height 0.7s cubic-bezier(.68,-0.55,.27,1.55), box-shadow 0.3s",
        height: open ? "500px" : "90px",
        overflow: "hidden",
        cursor: "pointer",
      }}
      className={styles.bodyonwhite}
      onClick={() => setOpen((v) => !v)}
    >
      <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
        <div
          style={{
            width: 38,
            height: 38,
            borderRadius: "50%",
            background: "rgba(0,0,0,0.07)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontWeight: 700,
            color: "#1a7f6b",
            fontSize: 18,
            boxShadow: "0 2px 8px rgba(0,0,0,0.07)",
            letterSpacing: 1,
          }}
        >
          <span style={{ fontSize: 18, color: "#1a7f6b" }}>NE</span>
        </div>
        <h3 style={{ color: "#1a7f6b", fontSize: 20, margin: 0, fontWeight: 600, letterSpacing: 0.5 }}>
          Vyft program Nérethense AI
        </h3>
        <span
          style={{
            marginLeft: "auto",
            color: "#444",
            fontSize: 18,
            fontWeight: 500,
            transition: "transform 0.3s",
            transform: open ? "rotate(90deg)" : "rotate(0deg)",
          }}
        >
          ▸
        </span>
      </div>
      <div
        style={{
          opacity: open ? 1 : 0,
          transition: "opacity 0.5s",
          marginTop: open ? 18 : 0,
          height: open ? "auto" : 0,
          pointerEvents: open ? "auto" : "none",
          display: "flex",
          flexDirection: "column",
          gap: 12,
        }}
        onClick={e => e.stopPropagation()}
      >
        {/* Zone de discussion coulissante */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: 10,
            flex: 1,
            overflowY: "auto",
            scrollBehavior: "smooth",
            maxHeight: 340, // Ajoute une hauteur max pour activer le scroll
          }}
        >
          {messages.map((msg, idx) => {
            // Si c'est le dernier message IA, on affiche avec l'effet d'écriture
            if (
              msg.from === "ai" &&
              idx === messages.length - 1 &&
              !loading
            ) {
              return (
                <Bubble key={idx} from={msg.from} text="">
                  <TypingText text={msg.text} />
                </Bubble>
              );
            }
            return <Bubble key={idx} from={msg.from} text={msg.text} />;
          })}
          {loading && (
            <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 12 }}>
              <div
                style={{
                  width: 24,
                  height: 24,
                  borderRadius: "50%",
                  background: "rgba(0,0,0,0.07)",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  fontWeight: 700,
                  color: "#1a7f6b",
                  fontSize: 15,
                  boxShadow: "0 2px 8px rgba(0,0,0,0.07)",
                  letterSpacing: 1,
                }}
              >
                <span style={{ fontSize: 13, color: "#1a7f6b" }}>NE</span>
              </div>
              <TypingBubble />
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>
        <form
          style={{ display: "flex", gap: 8, marginTop: 8 }}
          onSubmit={e => { e.preventDefault(); sendMessage(); }}
        >
          <input
            type="text"
            value={input}
            onChange={e => setInput(e.target.value)}
            placeholder="Votre question..."
            style={{
              flex: 1,
              borderRadius: 12,
              border: "1px solid #e0dbdd",
              padding: "8px 12px",
              fontSize: 15,
              fontWeight: 500,
              background: "rgba(0,0,0,0.07)",
              color: "#222",
              outline: "none",
            }}
            disabled={loading}
          />
          <button
            type="submit"
            style={{
              borderRadius: 12,
              border: "none",
              background: "#1a7f6b",
              color: "#fff",
              fontWeight: 600,
              fontSize: 15,
              padding: "8px 18px",
              cursor: loading ? "not-allowed" : "pointer",
              opacity: loading ? 0.7 : 1,
              transition: "opacity 0.2s",
            }}
            disabled={loading}
          >
            Envoyer
          </button>
        </form>
      </div>
      <style jsx global>{`
        @keyframes dotBounce {
          0%, 80%, 100% { transform: translateY(0); }
          40% { transform: translateY(-8px); }
        }
      `}</style>
    </div>
  );
}

// Ajoute ce composant pour l'effet d'écriture lettre par lettre
function TypingText({ text }: { text: string }) {
  const [displayed, setDisplayed] = useState("");
  const index = useRef(0);

  useEffect(() => {
    setDisplayed("");
    index.current = 0;
    if (!text) return;
    const interval = setInterval(() => {
      setDisplayed((prev) => prev + text[index.current]);
      index.current++;
      if (index.current >= text.length) clearInterval(interval);
    }, 18); // Vitesse d'écriture (ms)
    return () => clearInterval(interval);
  }, [text]);

  return <span>{displayed}</span>;
}

// Modifie Bubble pour accepter des enfants (children)
function Bubble({
  from,
  text,
  children,
}: {
  from: "ai" | "user";
  text: string;
  children?: React.ReactNode;
}) {
  return (
    <div
      style={{
        alignSelf: from === "user" ? "flex-end" : "flex-start",
        background: from === "ai" ? "rgba(255,255,255,0.10)" : "#e0dbdd",
        color: from === "ai" ? "#f5f6fa" : "#222",
        borderRadius: 12,
        padding: "10px 16px",
        maxWidth: "80%",
        fontSize: 15,
        fontWeight: 500,
        boxShadow: "0 2px 8px rgba(0,0,0,0.10)",
        transition: "transform 0.4s cubic-bezier(.68,-0.55,.27,1.55)",
        transform: "translateY(0)",
        border: from === "ai" ? "1px solid #353a40" : "none",
      }}
    >
      {children ? children : text}
    </div>
  );
}

function TypingBubble() {
  return (
    <div
      style={{
        background: "rgba(0,0,0,0.07)",
        borderRadius: 12,
        padding: "6px 14px",
        minWidth: 60,
        display: "flex",
        alignItems: "center",
        gap: 4,
        fontSize: 15,
        color: "#444",
        fontWeight: 500,
        boxShadow: "0 2px 8px rgba(0,0,0,0.07)",
        letterSpacing: 0.5,
      }}
    >
      <span style={{ marginRight: 6 }}>Écrit...</span>
      <TypingDots />
    </div>
  );
}

function TypingDots() {
  return (
    <span style={{ display: "inline-block", minWidth: 24 }}>
      <Dot delay={0} />
      <Dot delay={0.2} />
      <Dot delay={0.4} />
    </span>
  );
}

function Dot({ delay }: { delay: number }) {
  return (
    <span
      style={{
        display: "inline-block",
        width: 6,
        height: 6,
        borderRadius: "50%",
        background: "#1a7f6b",
        margin: "0 2px",
        animation: `dotBounce 1s infinite`,
        animationDelay: `${delay}s`,
        verticalAlign: "middle",
      }}
    />
  );
}